    expect(equivalentPlan.planSha256).not.toBe(firstPlan.planSha256)
    expect(m80HostedIntentPath(equivalentPlan, "migration")).toBe(m80HostedIntentPath(firstPlan, "migration"))
    const directory = await mkdtemp(join(tmpdir(), "m80-hosted-prep-")); temporary.push(directory)
    const path = join(directory, m80HostedIntentPath(firstPlan, "migration").split("/").pop()!)
    await writeM80HostedEvidenceOnce(path, { status: "intent_sealed_not_executed" })
